create index wpi_equipment_price_reviews_submitted_by_idx on public.wpi_equipment_price_reviews(submitted_by); create index wpi_equipment_price_reviews_reviewed_by_idx on public.wpi_equipment_price_reviews(reviewed_by) where reviewed_by is not null; drop policy if exists wpi_equipment_price_reviews_insert on public.wpi_equipment_price_reviews; create policy wpi_equipment_price_reviews_insert on public.wpi_equipment_price_reviews for insert to authenticated with check (private.wpi_has_permission(organization_id, 'price.review') and submitted_by = (select auth.uid()));;
